#coloca os dados nessa variavel 
texto_base64_vindo_do_json = ""


#Funcao para desconverter os bytes das imagens em imagens
def desconverter_image(json_text, ext):
    image_bytes = base64.b64decode(json_text)
    name_file = f'image_desconvertida.{ext}'
    
    with open(name_file, 'wb') as file:
        file.write(image_bytes)
    print(f'Sucesso! Imagem recriada e salva como {name_file}')
    
desconverter_image(texto_base64_vindo_do_json, 'png')